CREATE OR REPLACE FUNCTION public.mha_admin_set_role_permission(p_role_id bigint, p_submodule_code text, p_access_level text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nbegin\n if auth.uid() is null or not exists(select 1 from public.mha_super_admin_identity sa join public.mha_user_profile u on u.user_id=sa.user_id where sa.user_id=auth.uid() and u.is_active and u.is_super_admin) then raise exception 'Super Admin access required' using errcode='42501';end if;\n if not exists(select 1 from public.mha_role r join public.mha_company c on c.id=r.company_id where r.id=p_role_id and r.is_active and c.is_active) then raise exception 'Active company role required';end if;\n if p_submodule_code not in ('dashboard','order','orderHistory','inventory','recipe','config','production') or p_access_level not in ('NONE','VIEW','EDIT') then raise exception 'Invalid submodule or permission';end if;\n if p_access_level='NONE' then\n  delete from public.mha_role_permission where role_id=p_role_id and submodule_code=p_submodule_code;\n else\n  insert into public.mha_role_permission(role_id,submodule_code,access_level) values(p_role_id,p_submodule_code,p_access_level)\n  on conflict(role_id,submodule_code) do update set access_level=excluded.access_level;\n end if;\nend $function$\n

-- Explicit least-privilege grants are required on a fresh migration replay.
REVOKE ALL ON FUNCTION public.mha_admin_set_role_permission(bigint,text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.mha_admin_set_role_permission(bigint,text,text) TO authenticated;
